/*
 * Static symbol table for sdl2-compat on Vega.
 *
 * sdl2-compat normally dlopen()s libSDL3.so and looks up each SDL3 function by name. On Vega,
 * SDL3 (with our video/audio drivers) is linked statically into the app, with its symbols renamed
 * SDL_* -> SDL3V_* (rename-sdl3.cmake) so they don't clash with the SDL2 API that sdl2-compat
 * defines. This table maps the names sdl2-compat asks for to those renamed functions; it is
 * generated by the preprocessor from sdl2-compat's own list of SDL3 symbols (sdl3_syms.h).
 *
 * SPDX-FileCopyrightText: 2026 Mitul Shah
 * SPDX-License-Identifier: MIT
 */
#include <string.h>
#include <SDL3/SDL_platform_defines.h> /* sdl3_syms.h has per-platform entries (SDL_PLATFORM_LINUX) */

#define SDL3_SYM(rc, fn, params, args, ret) extern void SDL3V_##fn(void);
#include "sdl3_syms.h"

/* sdl3_syms.h entries end inconsistently (some with ';', varargs ones without), so each entry
 * becomes a complete statement inside a function, where a stray ';' is just an empty statement.
 * About 800 string compares per lookup, done once per symbol at startup. */
void *SDL2COMPAT_StaticSDL3Lookup(const char *name)
{
#define SDL3_SYM(rc, fn, params, args, ret) if (strcmp(name, "SDL_" #fn) == 0) return (void *)SDL3V_##fn;
#include "sdl3_syms.h"
    return NULL;
}
